Mesh<Point, double> result;
std::map<RT::Cell_handle, std::vector<Point>> cell_polygons;
std::map<RT::Cell_handle, bool> visited_cells;

// First pass: collect all infinite edges and mark their incident cells
for (auto eit = rt.finite_edges_begin(); eit != rt.finite_edges_end(); ++eit) {
    if (is_small_edge(rt, *eit, threshold)) {
        auto edge = *eit;
        auto cell = edge.first;
        int i = edge.second;
        int j = edge.third;

        // Mark both incident cells as visited
        visited_cells[cell] = true;
        visited_cells[rt.mirror_edge(edge).first] = true;
    }
}

// Second pass: for each visited cell, collect its vertices to form a polygon
for (auto const& [cell, _] : visited_cells) {
    std::vector<Point> polygon;
    for (int i = 0; i < 4; ++i) {
        if (i == cell->index(cell->neighbor(i))) continue; // Skip infinite vertex
        polygon.push_back(rt.dual(cell, i));
    }
    if (!polygon.empty()) {
        cell_polygons[cell] = polygon;
    }
}

// Third pass: create faces from the collected polygons
for (auto const& [cell, polygon] : cell_polygons) {
    if (polygon.size() >= 3) { // Ensure it's a valid polygon
        std::vector<double> edge_lengths;
        for (size_t i = 0; i < polygon.size(); ++i) {
            size_t j = (i + 1) % polygon.size();
            edge_lengths.push_back(std::sqrt(CGAL::squared_distance(polygon[i], polygon[j])));
        }
        result.add_face(polygon, edge_lengths);
    }
}

return result;

